<?php
namespace App\Services;
use App\Models\Fixture; use App\Models\ResultSubmission; use Illuminate\Support\Facades\DB;
class ResultService { public function __construct(private readonly AuditService $audit) {} public function approve(ResultSubmission $result, ?string $notes=null): void { DB::transaction(function() use($result,$notes){ $result->refresh(); abort_unless($result->status==='submitted',422,'Only submitted results can be approved.'); $before=$result->only($result->getFillable()); $result->update(['status'=>'approved','reviewed_by'=>auth()->id(),'reviewed_at'=>now(),'review_notes'=>$notes]); $fixture=Fixture::findOrFail($result->fixture_id); $fixture->update(['status'=>'completed','completed_at'=>now()]); $this->audit->record('result.approved',$result,$before,$result->only($result->getFillable())); }); } public function reject(ResultSubmission $result,string $notes): void { DB::transaction(function() use($result,$notes){ abort_unless($result->status==='submitted',422,'Only submitted results can be rejected.'); $before=$result->only($result->getFillable()); $result->update(['status'=>'rejected','reviewed_by'=>auth()->id(),'reviewed_at'=>now(),'review_notes'=>$notes]); $this->audit->record('result.rejected',$result,$before,$result->only($result->getFillable())); }); } }
